import{c as e,Z as o,Q as r,j as s,m as n,o as a}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"江城子·密州出猎","description":"","frontmatter":{"title":"江城子·密州出猎","author":"苏轼","dynasty":"宋"},"headers":[],"relativePath":"books/shici/songci/10.md","filePath":"books/shici/songci/10.md"}'),u={name:"books/shici/songci/10.md"};function h(c,i,p,d,q,_){const t=o("PoemAuthor"),l=o("PoemNav");return r(),s("div",null,[i[0]||(i[0]=n('<h1 id="江城子·密州出猎" tabindex="-1">江城子·密州出猎 <a class="header-anchor" href="#江城子·密州出猎" aria-label="Permalink to &quot;江城子·密州出猎&quot;">​</a></h1><p><strong>[宋] <a href="/authors/sushi.html">苏轼</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>老夫聊发少年狂，左牵黄，右擎苍，锦帽貂裘，千骑卷平冈。为报倾城随太守，亲射虎，看孙郎。</p><p>酒酣胸胆尚开张。鬓微霜，又何妨！持节云中，何日遣冯唐？会挽雕弓如满月，西北望，射天狼。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>江城子：词牌名</li><li>密州：今山东省诸城市</li><li>出猎：外出打猎</li><li>老夫：词人自称，当时苏轼年仅四十</li><li>聊发：姑且抒发</li><li>少年狂：少年人的豪情壮志</li><li>左牵黄：左手牵着黄狗</li><li>右擎苍：右手举着苍鹰</li><li>锦帽貂裘：华贵的猎装</li><li>千骑：形容随从众多</li><li>卷平冈：席卷平坦的山冈</li><li>倾城：全城的人</li><li>太守：指苏轼自己，当时他任密州知州</li><li>孙郎：指孙权，曾亲自射虎</li><li>酒酣：酒兴正浓</li><li>胸胆尚开张：胸怀开阔，胆气豪壮</li><li>鬓微霜：鬓角微微发白</li><li>持节云中：典出《史记》，冯唐持节赦免魏尚</li><li>会挽：将要拉满</li><li>雕弓：雕饰精美的弓</li><li>天狼：天狼星，古代认为它象征侵扰西北边境的西夏</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>老夫姑且抒发一下少年人的豪情，左手牵着黄狗，右手举着苍鹰，头戴锦帽，身穿貂裘，率领千骑席卷平坦的山冈。为了报答全城百姓跟随太守出猎的盛情，我要亲自射虎，像当年的孙权一样。</p><p>酒兴正浓时胸怀开阔胆气豪壮。鬓角微微发白，又有什么关系！什么时候朝廷能像派遣冯唐赦免魏尚那样重用我呢？我要拉满雕弓如满月，向西北望去，射向那天狼星。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是苏轼任密州知州时所作，描写了一次出猎的盛况，表达了词人渴望建功立业、报效国家的雄心壮志，是苏轼豪放词的代表作之一。</p><p>上片写出猎的盛况。&quot;老夫聊发少年狂&quot;，开篇就点明了词人的豪情。&quot;左牵黄，右擎苍，锦帽貂裘&quot;，写出了出猎时的装束和气派。&quot;千骑卷平冈&quot;，以&quot;卷&quot;字写出了出猎队伍的浩大声势。&quot;为报倾城随太守，亲射虎，看孙郎&quot;，写词人要以亲自射虎来报答百姓的热情，自比孙权，展现了豪迈的气概。</p><p>下片抒发报国之志。&quot;酒酣胸胆尚开张&quot;，写酒后的豪情。&quot;鬓微霜，又何妨&quot;，表达了不服老的壮志。&quot;持节云中，何日遣冯唐&quot;，用冯唐持节赦免魏尚的典故，表达了渴望被朝廷重用的心情。&quot;会挽雕弓如满月，西北望，射天狼&quot;，以拉弓射天狼的雄姿，表达了抗击外敌、保卫国家的决心。</p><p>全词气势磅礴，豪情万丈，将出猎的盛况与报国的壮志完美融合，是苏轼豪放词风的典型体现。</p>',15)),a(t,{name:"苏轼",years:"1037年－1101年",desc:"字子瞻，号东坡居士，北宋著名文学家、书法家、画家，唐宋八大家之一。其词开豪放一派，与辛弃疾并称“苏辛”。",link:"/authors/sushi"}),a(l)])}const b=e(u,[["render",h]]);export{f as __pageData,b as default};
